export const GPROMS_STD_LIB_WASM_BASE64 =
  "";

let cachedWasmBytes: Uint8Array | undefined;

/**
 * Decodes the pre-bundled `@modelscript/gproms-std-lib` `runtime.wasm` binary in Node.js, Browsers, or Web Workers.
 */
export function getGpromsStdLibWasmBytes(): Uint8Array {
  if (!cachedWasmBytes) {
    cachedWasmBytes = decodeBase64Wasm(GPROMS_STD_LIB_WASM_BASE64);
  }
  return cachedWasmBytes;
}
